begin;
select no_plan();
select has_function('public','grant_test_collection',array['uuid','uuid'],'administrator-only package grant exists');
insert into auth.users(id) values ('9f100000-0000-0000-0000-000000000001'),('9f100000-0000-0000-0000-000000000002');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"9f100000-0000-0000-0000-000000000001"}',true);
select public.bootstrap_identity();
select public.create_family();
reset role;
select set_config('test.grant_home',(select family_id::text from public.family_members where user_id='9f100000-0000-0000-0000-000000000001'),true);
insert into public.room_layouts(family_id,version) values(current_setting('test.grant_home')::uuid,7);
select set_config('test.grant_result',public.grant_test_collection('9f200000-0000-0000-0000-000000000001','9f100000-0000-0000-0000-000000000001')::text,true);
select is((select miao_coins from public.wallets where owner_id='9f100000-0000-0000-0000-000000000001'),2030,'adds 2000 without resetting existing balance');
select is((select eagle_pounds from public.wallets where owner_id='9f100000-0000-0000-0000-000000000001'),12,'adds 12 eagle');
select is((select gems from public.wallets where owner_id='9f100000-0000-0000-0000-000000000001'),12,'adds 12 gems');
select is((select count(*)::int from public.wallet_entries where operation_id='9f200000-0000-0000-0000-000000000001' and kind='test_grant'),1,'one explicit test ledger entry');
select is((select count(*)::int from public.furniture_inventory where source_id='9f200000-0000-0000-0000-000000000001'),6,'six existing souvenir styles');
select ok((select bool_and(purchased_by='9f100000-0000-0000-0000-000000000001' and source='test_grant' and source_trip_id is null) from public.furniture_inventory where source_id='9f200000-0000-0000-0000-000000000001'),'personal test inventory with no fabricated trips');
select is((select count(*)::int from public.test_photo_unlocks where owner_id='9f100000-0000-0000-0000-000000000001'),12,'all two appearances by six destinations unlocked');
select is((select count(*)::int from public.cats where family_id=current_setting('test.grant_home')::uuid),0,'no fabricated cats');
select is((select count(*)::int from public.cat_trips where family_id=current_setting('test.grant_home')::uuid),0,'no fabricated travel or fee exemptions');
select is((select version::int from public.room_layouts where family_id=current_setting('test.grant_home')::uuid),7,'room version unchanged');
select is(public.grant_test_collection('9f200000-0000-0000-0000-000000000001','9f100000-0000-0000-0000-000000000001'),current_setting('test.grant_result')::jsonb,'lost receipt retry returns exact original receipt');
select is((select miao_coins from public.wallets where owner_id='9f100000-0000-0000-0000-000000000001'),2030,'retry never adds money twice');
select is((select count(*)::int from public.furniture_inventory where source_id='9f200000-0000-0000-0000-000000000001'),6,'retry never copies inventory');
select throws_ok($$select public.grant_test_collection('9f200000-0000-0000-0000-000000000001','9f100000-0000-0000-0000-000000000002')$$,'22023','Test grant request belongs to another owner','request ownership fixed');
select throws_ok($$select public.grant_test_collection('9f200000-0000-0000-0000-000000000002','9f100000-0000-0000-0000-000000000002')$$,'22023','Existing wallet and family required','missing account scope rejected atomically');
select ok(not exists(select 1 from public.test_account_grants where request_id='9f200000-0000-0000-0000-000000000002'),'rejected grant leaves no receipt');
select ok(not has_function_privilege('authenticated','public.grant_test_collection(uuid,uuid)','execute'),'member cannot mint package');
select ok(not has_function_privilege('anon','public.grant_test_collection(uuid,uuid)','execute'),'anon cannot mint package');
set local role authenticated;
select is(jsonb_array_length(public.family_album()->'photos'),12,'recipient album shows all pictures');
select ok((select bool_and(x->>'source'='test_grant') from jsonb_array_elements(public.family_album()->'photos') x),'photos disclose test unlock provenance');
select is(jsonb_array_length(public.furniture_state()->'inventory'),18,'editor exposes six souvenirs and twelve automatically unlocked photos');
select throws_ok($$select * from public.test_photo_unlocks$$,'42501',null,'member cannot enumerate or write unlock table');
select set_config('request.jwt.claims','{"sub":"9f100000-0000-0000-0000-000000000002"}',true);
select is(jsonb_array_length(public.family_album()->'photos'),0,'outsider sees no personal unlocks');
reset role;
insert into public.family_members(family_id,user_id) values(current_setting('test.grant_home')::uuid,'9f100000-0000-0000-0000-000000000002');
set local role authenticated;
select is(jsonb_array_length(public.family_album()->'photos'),0,'second member is not personally granted all photos');
reset role;
select * from finish();
rollback;
